function compute(state) {
  var a = state.a, eta = state.eta, x0 = state.x0, K = Math.round(state.steps);
  function f(x) { return 0.5 * a * x * x; }
  var gx = [], gy = [];
  for (var i = 0; i <= 80; i++) { var x = -4 + 8 * i / 80; gx.push(x); gy.push(f(x)); }
  var xs = [x0], fs = [f(x0)], ks = [0];
  for (var k = 1; k <= K; k++) { var xn = xs[k - 1] - eta * a * xs[k - 1]; xs.push(xn); fs.push(f(xn)); ks.push(k); }
  var r = 1 - eta * a;
  return {
    values: { r: r, ratio_abs: Math.abs(r), eta_crit: 2 / a, eta_opt: 1 / a, x_final: xs[K], f_final: fs[K], y_top: f(4) * 1.05, loss_top: Math.max(f(x0), 1e-9) * 1.3 },
    series: { gx: gx, gy: gy, xs: xs, fs: fs, ks: ks }
  };
}
